import Database from "better-sqlite3";
import { mkdirSync } from "fs";

// Ensure the uploads directory exists on startup
mkdirSync("/home/user/qwik-app/public/uploads", { recursive: true });

const dbPath = "/home/user/qwik-app/metadata.db";
export const db = new Database(dbPath);

// Initialize the files table
db.exec(`
  CREATE TABLE IF NOT EXISTS files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    size INTEGER NOT NULL,
    mime TEXT NOT NULL,
    tag TEXT NOT NULL
  )
`);

import type { RequestHandler } from "@builder.io/qwik-city";
import { db } from "../../../lib/db";
import { writeFileSync } from "fs";
import { join } from "path";

export const onPost: RequestHandler = async (ev) => {
  try {
    const formData = await ev.request.formData();
    const file = formData.get("file");
    const tag = formData.get("tag");

    // Check if file is missing or invalid
    if (!file || typeof file === "string" || !(file instanceof File) || file.name === "" || file.size === 0) {
      ev.json(400, { error: "File is missing or invalid" });
      return;
    }

    // Check if tag is missing or invalid
    if (!tag || typeof tag !== "string" || tag.trim() === "") {
      ev.json(400, { error: "Tag is missing or invalid" });
      return;
    }

    const uploadDir = "/home/user/qwik-app/public/uploads";
    const filePath = join(uploadDir, file.name);
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);
    writeFileSync(filePath, buffer);

    const stmt = db.prepare(`
      INSERT INTO files (name, size, mime, tag)
      VALUES (?, ?, ?, ?)
    `);
    const result = stmt.run(file.name, file.size, file.type || "application/octet-stream", tag);
    const insertId = result.lastInsertRowid;

    ev.status(201);
    ev.json(201, {
      id: Number(insertId),
      name: file.name,
      size: file.size,
      mime: file.type || "application/octet-stream",
      tag: tag,
    });
  } catch (error: any) {
    ev.json(400, { error: error.message || "An error occurred during upload" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { db } from "../../../lib/db";

export const onGet: RequestHandler = async (ev) => {
  try {
    const stmt = db.prepare("SELECT id, name, size, mime, tag FROM files");
    const files = stmt.all();
    ev.json(200, files);
  } catch (error: any) {
    ev.json(500, { error: error.message || "An error occurred while listing files" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { db } from "../../../lib/db";
import { unlinkSync, existsSync } from "fs";
import { join } from "path";

interface FileRecord {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

export const onDelete: RequestHandler = async (ev) => {
  try {
    const id = parseInt(ev.params.id, 10);
    if (isNaN(id)) {
      ev.json(400, { error: "Invalid ID format" });
      return;
    }

    const stmtSelect = db.prepare("SELECT id, name, size, mime, tag FROM files WHERE id = ?");
    const file = stmtSelect.get(id) as FileRecord | undefined;

    if (!file) {
      ev.json(404, { error: `File with ID ${id} not found` });
      return;
    }

    const filePath = join("/home/user/qwik-app/public/uploads", file.name);
    if (existsSync(filePath)) {
      try {
        unlinkSync(filePath);
      } catch (err) {
        // Proceed anyway as per requirements
      }
    }

    const stmtDelete = db.prepare("DELETE FROM files WHERE id = ?");
    stmtDelete.run(id);

    ev.json(200, { success: true });
  } catch (error: any) {
    ev.json(500, { error: error.message || "An error occurred during deletion" });
  }
};

import { component$, useStore, useVisibleTask$, $ } from "@builder.io/qwik";

interface FileItem {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

export default component$(() => {
  const state = useStore<{ files: FileItem[] }>({
    files: [],
  });

  const fetchFiles = $(async () => {
    try {
      const res = await fetch("/files/list");
      if (res.ok) {
        state.files = await res.json();
      }
    } catch (err) {
      console.error("Error fetching files:", err);
    }
  });

  useVisibleTask$(() => {
    fetchFiles();
  });

  const handleSubmit = $(async (e: Event) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    try {
      const res = await fetch("/files/upload", {
        method: "POST",
        body: formData,
      });

      if (res.ok) {
        form.reset();
        await fetchFiles();
      } else {
        const errData = await res.json();
        alert(errData.error || "Upload failed");
      }
    } catch (err) {
      console.error("Error uploading file:", err);
    }
  });

  const handleDelete = $(async (id: number) => {
    try {
      const res = await fetch(`/files/${id}`, {
        method: "DELETE",
      });

      if (res.ok) {
        await fetchFiles();
      } else {
        const errData = await res.json();
        alert(errData.error || "Deletion failed");
      }
    } catch (err) {
      console.error("Error deleting file:", err);
    }
  });

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>File Explorer</h1>

      <form id="upload-form" onSubmit$={handleSubmit} style={{ marginBottom: "20px" }}>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="file-input" style={{ display: "block", marginBottom: "5px" }}>File:</label>
          <input type="file" id="file-input" name="file" required />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="tag-input" style={{ display: "block", marginBottom: "5px" }}>Tag:</label>
          <input type="text" id="tag-input" name="tag" placeholder="e.g., documents, images" required />
        </div>
        <button type="submit">Upload</button>
      </form>

      <h2>Uploaded Files</h2>
      <div id="file-list">
        {state.files.length === 0 ? (
          <p>No files uploaded yet.</p>
        ) : (
          <ul style={{ listStyleType: "none", padding: 0 }}>
            {state.files.map((file) => (
              <li key={file.id} style={{ border: "1px solid #ccc", padding: "10px", marginBottom: "10px", borderRadius: "4px" }}>
                <div><strong>Name:</strong> {file.name}</div>
                <div><strong>Size:</strong> {file.size} bytes</div>
                <div><strong>MIME:</strong> {file.mime}</div>
                <div><strong>Tag:</strong> {file.tag}</div>
                <button
                  class="delete-btn"
                  data-id={file.id}
                  onClick$={() => handleDelete(file.id)}
                  style={{ marginTop: "5px", backgroundColor: "#ff4d4d", color: "#fff", border: "none", padding: "5px 10px", borderRadius: "3px", cursor: "pointer" }}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
});

